  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Determine whether this booking satisfies all booking rules, including trip existence,
   * seat availability, non-overlapping customer bookings on the same day, and the
   * "more than 2 hours before departure" constraint.
   * Algorithm:
   * 1. If bookingDate, customer, or trip is null, return false.
   * 2. Verify that numberOfSeats is positive.
   * 3. Verify that the trip has enough remaining seats for numberOfSeats.
   * 4. Check that the booking time is strictly earlier than the trip departure time by more than 2 hours.
   *    - If the difference is exactly 2 hours, reject the booking.
   * 5. For each existing booking of the customer:
   *    - If the existing booking is on the same calendar day and its trip overlaps with this trip,
   *      reject the booking.
   * 6. If all checks pass, return true.
   * 7. Otherwise return false.
   * Related Features:
   * - bookingDate
   * - numberOfSeats
   * - customer
   * - trip
   * Related Classes: Booking, Customer, Trip, EDate
   * Input:
   * - None explicitly; the operation uses the current Booking instance state.
   * - bookingDate: date of the booking request, must be non-null.
   * - customer: associated customer, must be non-null.
   * - trip: associated trip, must be non-null.
   * - numberOfSeats: requested seat count, must be > 0.
   * Output:
   * - boolean:
   *   - true if the booking is eligible under all constraints.
   *   - false otherwise.
   * Pre-condition:
   * - The Booking instance is initialized.
   * - bookingDate, customer, and trip are available unless the input is invalid.
   * - The trip departure time and the booking time are comparable in a consistent date-time format.
   * Post-condition:
   * - If true is returned, the booking satisfies all eligibility checks.
   * - If false is returned, no booking-side state is changed.
   * - The trip seat inventory is not modified by this operation.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (bookingDate == null || customer == null || trip == null)
    {
      return false;
    }
    if (numberOfSeats <= 0)
    {
      return false;
    }
    if (trip.getNumberOfSeats() < numberOfSeats)
    {
      return false;
    }

    long bookingTime = bookingDate.getTime();
    Date departureDate = bookingDate;
    String departureTime = trip.getDepartureTime();
    if (departureTime == null)
    {
      return false;
    }

    long tripTimeMillis;
    try
    {
      tripTimeMillis = java.sql.Time.valueOf(departureTime).getTime();
    }
    catch (IllegalArgumentException e)
    {
      try
      {
        tripTimeMillis = new Date(Long.parseLong(departureTime)).getTime();
      }
      catch (Exception ex)
      {
        return false;
      }
    }

    Calendar bookingCal = Calendar.getInstance();
    bookingCal.setTime(bookingDate);
    Calendar departureCal = Calendar.getInstance();
    departureCal.setTime(new Date(departureDate.getTime()));
    departureCal.set(Calendar.HOUR_OF_DAY, (int) (tripTimeMillis / (60L * 60L * 1000L)) % 24);
    departureCal.set(Calendar.MINUTE, (int) (tripTimeMillis / (60L * 1000L)) % 60);
    departureCal.set(Calendar.SECOND, (int) (tripTimeMillis / 1000L) % 60);
    departureCal.set(Calendar.MILLISECOND, 0);

    long diffMillis = departureCal.getTimeInMillis() - bookingTime;
    if (diffMillis <= 2L * 60L * 60L * 1000L)
    {
      return false;
    }

    if (customer.getBookings() != null)
    {
      for (Booking existingBooking : customer.getBookings())
      {
        if (existingBooking == null || existingBooking == this)
        {
          continue;
        }
        Date existingDate = existingBooking.getBookingDate();
        if (existingDate == null)
        {
          continue;
        }
        Calendar c1 = Calendar.getInstance();
        c1.setTime(existingDate);
        Calendar c2 = Calendar.getInstance();
        c2.setTime(bookingDate);
        boolean sameDay = c1.get(Calendar.YEAR) == c2.get(Calendar.YEAR)
            && c1.get(Calendar.DAY_OF_YEAR) == c2.get(Calendar.DAY_OF_YEAR);
        if (sameDay && existingBooking.overlapsWith(trip))
        {
          return false;
        }
      }
    }

    return true;
    
  }

